class Solution {
  public int longestSubarray(int[] nums, int k) {
    int MAX = 100_001;
    int[] spf = new int[MAX];
    for (int i = 2; i < MAX; i++) {
      if (spf[i] != 0) continue;
      for (int j = i; j < MAX; j += i) if (spf[j] == 0) spf[j] = i;
    }
    int[] count = new int[MAX];
    int distinct = 0, left = 0, best = 0;
    for (int r = 0; r < nums.length; r++) {
      for (int x = nums[r]; x > 1; ) {
        int p = spf[x];
        while (x % p == 0) x /= p;
        if (count[p]++ == 0) distinct++;
      }
      while (distinct > k && left <= r) {
        for (int x = nums[left]; x > 1; ) {
          int p = spf[x];
          while (x % p == 0) x /= p;
          if (--count[p] == 0) distinct--;
        }
        left++;
      }
      best = Math.max(best, r - left + 1);
    }
    return best;
  }
}
